import React, { useState } from 'react';

const QuanLyThongBaoAdmin = () => {
    // 3 mục: 'xem' (Xem nhóm chung), 'gui-chung' (Đăng tin tòa nhà), 'gui-rieng' (Nhắn riêng)
    const [activeTab, setActiveTab] = useState('xem');

    return (
        <div style={styles.container}>
            <header style={styles.header}>
                <h2 style={styles.mainTitle}>📢 Hệ Thống Điều Phối Thông Báo</h2>
                <div style={styles.tabBar}>
                    <button 
                        onClick={() => setActiveTab('xem')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'xem' ? '#ed6c02' : '#eee', color: activeTab === 'xem' ? '#fff' : '#666'}}
                    >
                        👥 Xem nhóm chung
                    </button>
                    <button 
                        onClick={() => setActiveTab('gui-chung')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'gui-chung' ? '#2e7d32' : '#eee', color: activeTab === 'gui-chung' ? '#fff' : '#666'}}
                    >
                        📣 Gửi thông báo chung
                    </button>
                    <button 
                        onClick={() => setActiveTab('gui-rieng')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'gui-rieng' ? '#1976d2' : '#eee', color: activeTab === 'gui-rieng' ? '#fff' : '#666'}}
                    >
                        💬 Gửi tin riêng
                    </button>
                </div>
            </header>

            <div style={styles.mainCard}>
                {/* 1. XEM NHÓM CHUNG: Nơi Admin quản lý các bài đăng của cư dân */}
                {activeTab === 'xem' && (
                    <div>
                        <h3 style={{color: '#ed6c02', marginBottom: '15px'}}>Dòng thời gian nhóm chung</h3>
                        <div style={styles.postCard}>
                            <div style={styles.postHeader}>
                                <strong>Cư dân: Nguyễn Văn A (Phòng A102)</strong>
                                <span style={styles.timeLabel}>10:45 - Hôm nay</span>
                            </div>
                            <p style={styles.postContent}>Mọi người ơi, có ai thấy chìa khóa xe của mình ở khu vực hầm để xe không ạ?</p>
                            <div style={styles.adminAction}>
                                <button style={styles.btnDelete}>Xóa bài vi phạm</button>
                                <button style={styles.btnReply}>Phản hồi cư dân</button>
                            </div>
                        </div>
                    </div>
                )}

                {/* 2. GỬI THÔNG BÁO CHUNG: Đăng tin cho toàn tòa nhà (Như ảnh 10:27:14) */}
                {activeTab === 'gui-chung' && (
                    <div className="fade-in">
                        <h3 style={{color: '#2e7d32', marginBottom: '20px'}}>Tạo thông báo toàn tòa nhà</h3>
                        <input type="text" placeholder="Tiêu đề thông báo..." style={styles.input} />
                        <textarea placeholder="Nội dung gửi đến toàn bộ cư dân..." style={styles.textarea} />
                        <button style={{...styles.submitBtn, backgroundColor: '#2e7d32'}}>🚀 Gửi thông báo công khai</button>
                    </div>
                )}

                {/* 3. GỬI TIN RIÊNG: Nhắn trực tiếp cho 1 cư dân */}
                {activeTab === 'gui-rieng' && (
                    <div className="fade-in">
                        <h3 style={{color: '#1976d2', marginBottom: '20px'}}>Soạn tin nhắn gửi riêng biệt</h3>
                        <input type="text" placeholder="Gửi đến: Nhập số phòng hoặc tên cư dân (Vd: A205)..." style={{...styles.input, borderColor: '#1976d2'}} />
                        <textarea placeholder="Nội dung trao đổi bảo mật..." style={styles.textarea} />
                        <button style={{...styles.submitBtn, backgroundColor: '#1976d2'}}>📩 Gửi tin nhắn bảo mật</button>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    container: { padding: '20px', width: '100%', maxWidth: '950px', margin: '0 auto' },
    header: { textAlign: 'center', marginBottom: '30px' },
    mainTitle: { fontSize: '24px', fontWeight: 'bold', color: '#333' },
    tabBar: { display: 'inline-flex', gap: '10px', backgroundColor: '#f5f5f5', padding: '6px', borderRadius: '14px', marginTop: '20px' },
    tabBtn: { padding: '12px 25px', border: 'none', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', transition: '0.3s' },
    mainCard: { backgroundColor: '#fff', padding: '35px', borderRadius: '25px', boxShadow: '0 10px 40px rgba(0,0,0,0.06)', minHeight: '400px' },
    input: { width: '100%', padding: '15px', marginBottom: '15px', borderRadius: '12px', border: '1px solid #eee', backgroundColor: '#fafafa', boxSizing: 'border-box' },
    textarea: { width: '100%', padding: '15px', height: '160px', marginBottom: '20px', borderRadius: '12px', border: '1px solid #eee', backgroundColor: '#fafafa', resize: 'none', boxSizing: 'border-box' },
    submitBtn: { width: '100%', padding: '16px', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer' },
    postCard: { border: '1px solid #f0f0f0', padding: '20px', borderRadius: '15px', marginBottom: '15px', backgroundColor: '#fff' },
    postHeader: { display: 'flex', justifyContent: 'space-between', marginBottom: '10px', fontSize: '14px' },
    timeLabel: { color: '#bbb' },
    postContent: { color: '#444', lineHeight: '1.5' },
    adminAction: { marginTop: '15px', display: 'flex', gap: '10px' },
    btnDelete: { background: '#fff1f0', color: '#f5222d', border: '1px solid #ffa39e', padding: '6px 15px', borderRadius: '6px', cursor: 'pointer', fontSize: '12px' },
    btnReply: { background: '#f6ffed', color: '#52c41a', border: '1px solid #b7eb8f', padding: '6px 15px', borderRadius: '6px', cursor: 'pointer', fontSize: '12px' }
};

export default QuanLyThongBaoAdmin;
